insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_57_v1'
from (values
('127.391.d.1.A',3,'Which engineering discipline is traditionally credited as the oldest branch, dealing with roads, bridges and buildings?','["Civil engineering", "Software engineering", "Chemical engineering", "Aerospace engineering"]'::jsonb,0,'Civil engineering grew from building roads, aqueducts and structures.','original'),
('127.391.d.1.A',4,'The invention of the steam engine mainly drove which period of change in manufacturing?','["The Space Race", "The Industrial Revolution", "The Renaissance", "The Information Age"]'::jsonb,1,'Steam power moved work from hand tools to factories.','original'),
('127.391.d.1.B',3,'A technological system turns raw materials into a finished product. The raw materials are the system''s:','["outputs", "constraints", "inputs", "feedback"]'::jsonb,2,'Inputs go into a system; outputs come out.','original'),
('127.391.d.1.B',4,'In a wind turbine system, the electricity delivered to the grid is the:','["process", "constraint", "input", "output"]'::jsonb,3,'The result a system delivers is its output.','original'),
('127.391.d.1.C',3,'A closed-loop control system differs from an open-loop system because it uses:','["feedback to adjust its output", "a larger motor", "no power source", "only manual input"]'::jsonb,0,'Closed-loop systems sense results and correct themselves.','original'),
('127.391.d.1.C',4,'A kitchen timer runs for a set time regardless of whether the food is cooked. This is an example of an:','["adaptive system", "open-loop system", "feedback system", "closed-loop system"]'::jsonb,1,'With no sensing of the result, the timer is open-loop.','original'),
('127.391.d.1.D',3,'In a car, the engine, transmission, and brakes work together so the vehicle can travel safely. This shows that subsystems:','["compete for power", "operate with no connection", "interact to achieve a common goal", "work separately"]'::jsonb,2,'Subsystems depend on each other to meet the system''s goal.','original'),
('127.391.d.1.D',4,'If one subsystem in a larger technological system fails, the other subsystems are most likely to:','["improve", "run faster", "stay the same", "be affected too"]'::jsonb,3,'Connected subsystems share effects, so a failure spreads.','original'),
('127.391.d.1.E',3,'Which career path focuses mainly on discovering new knowledge about the natural world?','["Scientist", "Engineer", "Technician", "Machinist"]'::jsonb,0,'Scientists study nature to discover knowledge.','original'),
('127.391.d.1.E',4,'An engineer differs from a scientist mainly because an engineer applies knowledge to:','["discover natural laws only", "design solutions to problems", "avoid testing ideas", "publish opinions"]'::jsonb,1,'Engineers use science and math to design solutions.','original'),
('127.391.d.1.F',3,'When researching an emerging technology, the most reliable sources are usually:','["advertising banners", "anonymous posts", "peer-reviewed or reputable industry publications", "rumors from friends"]'::jsonb,2,'Credible sources are reviewed and accountable.','original'),
('127.391.d.1.F',4,'Solid-state batteries are an example of an emerging technology because they:','["were invented centuries ago", "are no longer researched", "have been abandoned", "are still being developed for wide use"]'::jsonb,3,'Emerging technologies are new and still developing.','original'),
('127.391.d.1.G',3,'Which step usually comes first in the engineering design process?','["Define the problem", "Build the final product", "Present the results", "Test the prototype"]'::jsonb,0,'You must understand the problem before solving it.','original'),
('127.391.d.1.G',4,'After testing a prototype, the design team finds a flaw. The process then calls for them to:','["ignore the flaw", "redesign and improve", "stop the project", "skip testing"]'::jsonb,1,'Design is iterative: test, find flaws, improve.','original'),
('127.391.d.2.A',3,'In a technical report, the best writing style is:','["humorous", "long and vague", "clear and concise", "slang-filled"]'::jsonb,2,'Technical writing must be easy to understand.','original'),
('127.391.d.2.A',4,'To explain a part''s shape to a machinist who is not in the room, an engineer should include:','["a joke", "a guess", "a rumor", "a labeled drawing"]'::jsonb,3,'Drawings communicate shape and size exactly.','original'),
('127.391.d.2.B',3,'Entries in an engineering notebook should be:','["dated and signed", "erased when wrong", "left undated", "written in pencil only"]'::jsonb,0,'Dated, signed entries make the notebook a reliable record.','original'),
('127.391.d.2.B',4,'If you make a mistake in a bound engineering notebook, you should:','["use correction fluid", "draw a single line through it and initial", "erase it", "tear out the page"]'::jsonb,1,'Original entries must stay readable.','original'),
('127.391.d.2.C',3,'A quick hand drawing used to capture an early idea is called a:','["schematic", "blueprint", "sketch", "render"]'::jsonb,2,'Sketches record ideas quickly.','original'),
('127.391.d.2.C',4,'A major advantage of CAD over hand drafting is that designs can be:','["never changed", "drawn only on paper", "made without a computer", "edited and shared easily"]'::jsonb,3,'Digital files are easy to modify and share.','original'),
('127.391.d.2.D',3,'Which tool best shows how a measured value changes over time?','["Line graph", "Pie chart", "Word list", "Photograph"]'::jsonb,0,'Line graphs show trends over time.','original'),
('127.391.d.2.D',4,'To show what share of a project budget each category uses, an engineer would choose a:','["flow chart", "pie chart", "line graph", "scatter plot"]'::jsonb,1,'Pie charts show parts of a whole.','original'),
('127.391.d.2.E',3,'A digital engineering portfolio is used to:','["store only grades", "hide your projects", "show examples of your work", "replace all tests"]'::jsonb,2,'Portfolios show skills to schools and employers.','original'),
('127.391.d.2.E',4,'Which item would be best to include in an engineering portfolio?','["A grocery list", "A vacation photo album", "A game score", "A dimensioned drawing of a finished project"]'::jsonb,3,'Portfolios hold documentation of engineering work.','original'),
('127.391.d.2.F',3,'A shared online document lets team members:','["edit the same file at the same time", "lose all changes", "work only offline", "avoid sharing"]'::jsonb,0,'Cloud tools support real-time collaboration.','original'),
('127.391.d.2.F',4,'Version history in a collaboration tool is useful because it lets a team:','["delete every copy", "restore an earlier version", "hide who made changes", "block all editing"]'::jsonb,1,'Version history lets you undo bad changes.','original'),
('127.391.d.3.A',3,'Before using lab equipment, students are usually required to:','["borrow tools", "work alone", "pass a safety test", "skip orientation"]'::jsonb,2,'Safety tests confirm students know the rules.','original'),
('127.391.d.3.A',4,'Why must a safety test be passed with a perfect or near-perfect score before using a power tool?','["It saves paper", "It is just a tradition", "Tools only work after tests", "Small mistakes can cause serious injury"]'::jsonb,3,'Power tools leave little room for error.','original'),
('127.391.d.3.B',3,'When working in an engineering lab, safety glasses should be worn:','["whenever there is an eye hazard", "only on Fridays", "never indoors", "only by the teacher"]'::jsonb,0,'Eye protection is required where eyes can be injured.','original'),
('127.391.d.3.B',4,'Long hair and loose sleeves near rotating machinery should be:','["ignored", "tied back or secured", "left loose", "worn longer"]'::jsonb,1,'Loose items can catch and pull a person into the machine.','original'),
('127.391.d.3.C',3,'PPE stands for:','["personal power equipment", "public protection engineering", "personal protective equipment", "portable product evaluation"]'::jsonb,2,'PPE protects the wearer from hazards.','original'),
('127.391.d.3.C',4,'On a label, the word WARNING indicates a hazard that:','["is purely decorative", "is always fatal", "has no risk", "could result in serious injury"]'::jsonb,3,'WARNING signals a potentially serious hazard.','original'),
('127.391.d.3.D',3,'A material that can easily catch fire is classified as:','["flammable", "edible", "inert", "magnetic"]'::jsonb,0,'Flammable materials ignite easily.','original'),
('127.391.d.3.D',4,'A substance that eats away at metal and skin on contact is classified as:','["magnetic", "corrosive", "inert", "reflective"]'::jsonb,1,'Corrosives chemically damage materials and tissue.','original'),
('127.391.d.3.E',3,'Used solvent rags from the lab should be placed in:','["the regular trash", "a sink drain", "an approved, labeled waste container", "a backpack"]'::jsonb,2,'Hazardous waste needs proper containers.','original'),
('127.391.d.3.E',4,'Hazardous liquid waste should never be poured down a drain because it can:','["improve the water", "cool the pipes", "make the sink shiny", "contaminate the water supply"]'::jsonb,3,'Drains lead to water systems.','original'),
('127.391.d.3.F',3,'Cutting tools should be stored:','["clean, dry, and in their proper place", "dirty and loose", "scattered on benches", "wet in a bin"]'::jsonb,0,'Proper storage prevents rust and injury.','original'),
('127.391.d.3.F',4,'Before returning a power tool to storage, you should first:','["oil the cord", "unplug it and clean it", "hide it", "leave it running"]'::jsonb,1,'Disconnecting power and cleaning keeps tools safe.','original'),
('127.391.d.3.G',3,'A worn guard on a machine that is not repaired could lead to:','["better quality", "extra warranty", "serious injury", "faster work"]'::jsonb,2,'Missing or worn guards expose moving parts.','original'),
('127.391.d.3.G',4,'Negligent maintenance of lab equipment can create legal problems because the owner may be held:','["paid by the company", "immune from blame", "exempt from rules", "liable for injuries"]'::jsonb,3,'Failing to maintain equipment can make an owner legally responsible.','original'),
('127.391.d.3.H',3,'Which instrument measures an object''s outside diameter to a thousandth of an inch?','["Micrometer", "Yardstick", "Protractor", "Level"]'::jsonb,0,'Micrometers measure to 0.001 inch or finer.','original'),
('127.391.d.3.H',4,'Calipers are often chosen over a ruler when a measurement needs:','["less accuracy", "greater precision", "no tools", "guessing"]'::jsonb,1,'Calipers read smaller increments than a ruler.','original'),
('127.391.d.4.A',3,'The printing press changed society mainly by making information:','["slower to copy", "rarer", "cheaper and widely available", "harder to read"]'::jsonb,2,'Printing spread books and ideas to many people.','original'),
('127.391.d.4.A',4,'Smartphones have affected cultures by changing how people:','["breathe", "tell time only", "grow food only", "communicate and get information"]'::jsonb,3,'Phones changed daily communication and information access.','original'),
('127.391.d.4.B',3,'The cotton gin affected the economy of the American South by greatly increasing:','["cotton production", "fishing", "silk trade", "wool imports"]'::jsonb,0,'The gin made cleaning cotton much faster.','original'),
('127.391.d.4.B',4,'Which technology helped speed up news and business over long distances in the 1800s?','["The windmill", "The telegraph", "The abacus", "The sundial"]'::jsonb,1,'The telegraph sent messages by electric signal.','original'),
('127.391.d.4.C',3,'Technology often advances because people want to:','["avoid learning", "waste materials", "solve problems or meet needs", "stop change"]'::jsonb,2,'Needs and problems drive invention.','original'),
('127.391.d.4.C',4,'New technologies often build on earlier inventions, so progress is described as:','["random only", "isolated", "reversed", "cumulative"]'::jsonb,3,'Each advance builds on earlier knowledge.','original'),
('127.391.d.4.D',3,'A likely effect of widespread automation in factories is:','["fewer repetitive manual jobs", "more hand sorting", "slower output", "no robots"]'::jsonb,0,'Machines take over repetitive tasks.','original'),
('127.391.d.4.D',4,'Engineers predicting the effect of self-driving vehicles might expect:','["fewer sensors", "changes in how cities plan parking", "no impact on roads", "the end of electricity"]'::jsonb,1,'Predicting effects means thinking beyond the device.','original'),
('127.391.d.5.A',3,'Which activity is part of an engineering design process?','["Avoiding any feedback", "Skipping the research", "Testing and evaluating a prototype", "Guessing the final cost"]'::jsonb,2,'Testing and evaluating is a core step.','original'),
('127.391.d.5.A',4,'Why do design processes show arrows looping back to earlier steps?','["Loops are decorations", "Engineers forget steps", "Steps are done only once", "Designs are improved through repeated testing"]'::jsonb,3,'The process is iterative.','original'),
('127.391.d.5.B',3,'A material''s ability to resist being scratched or dented is called its:','["hardness", "density", "conductivity", "color"]'::jsonb,0,'Hardness measures resistance to surface deformation.','original'),
('127.391.d.5.B',4,'A material that can be pulled into thin wire without breaking is described as:','["porous", "ductile", "brittle", "fragile"]'::jsonb,1,'Ductile materials stretch before breaking.','original'),
('127.391.d.5.C',3,'Brainstorming is used to:','["count inventory", "calibrate tools", "generate many ideas", "delete every idea"]'::jsonb,2,'Brainstorming collects many possible ideas.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_57_v1'
from (values
('127.391.d.5.C',4,'Which technique breaks a large problem into smaller, easier parts?','["Duplication", "Avoidance", "Exaggeration", "Decomposition"]'::jsonb,3,'Decomposition makes big problems manageable.','original'),
('127.391.d.5.D',3,'Before adding a length given in feet to one in inches, you must first:','["convert them to the same unit", "guess the sum", "ignore the units", "round each one"]'::jsonb,0,'Only like units can be added.','original'),
('127.391.d.5.D',4,'A spacecraft was lost partly because teams mixed metric and English units. This shows why engineers must use:','["shorter reports", "consistent units", "rounded values", "larger numbers"]'::jsonb,1,'Mixed units caused the Mars Climate Orbiter failure.','original'),
('127.391.d.5.E',3,'Weighing the risks and benefits of a design means comparing:','["dates with times", "prices with names", "possible harms with possible gains", "colors with sizes"]'::jsonb,2,'Risk-benefit assessment compares harms and gains.','original'),
('127.391.d.5.E',4,'A design is most acceptable when its benefits:','["are hidden", "equal zero", "are unknown", "outweigh its risks"]'::jsonb,3,'Benefits should exceed risks.','original'),
('127.391.d.6.A',3,'Industrial robots are widely used on assembly lines to:','["weld and move parts", "teach classes", "cook for staff", "predict weather only"]'::jsonb,0,'Robots handle welding and material handling.','original'),
('127.391.d.6.A',4,'An automated process that keeps a tank at a set liquid level using sensors is an example of:','["random flow", "process control", "hand pumping", "manual guessing"]'::jsonb,1,'Process control holds a variable at a set point.','original'),
('127.391.d.6.B',3,'When designing a robot arm to lift a heavy part, the designer must consider the arm''s:','["favorite color", "brand slogan", "load capacity", "paint finish"]'::jsonb,2,'The arm must safely support the load.','original'),
('127.391.d.6.B',4,'In an automated system, a sensor sends data to a controller, which then commands an:','["invoice", "accountant", "umpire", "actuator"]'::jsonb,3,'Actuators carry out the controller''s commands.','original'),
('127.391.d.6.C',3,'A technician who installs and repairs automated machinery works in:','["robotics and automation", "food service only", "fashion retail", "floral design"]'::jsonb,0,'Maintaining automated machines is a robotics career.','original'),
('127.391.d.6.C',4,'Which job requires knowledge of programmable logic controllers?','["Librarian", "Automation technician", "Florist", "Barista"]'::jsonb,1,'PLCs run automated equipment.','original'),
('127.391.d.6.D',3,'Collaborative robots, designed to work safely beside people, are called:','["avatars", "modems", "cobots", "drones"]'::jsonb,2,'Cobots share workspaces with humans.','original'),
('127.391.d.6.D',4,'Using artificial intelligence to help a robot adapt to new tasks is an emerging trend in:','["weaving by hand", "pottery", "calligraphy", "automation"]'::jsonb,3,'AI is expanding what automated systems can do.','original'),
('127.391.d.7.A',3,'An electric motor changes electrical energy into:','["mechanical energy", "chemical energy", "sound only", "nuclear energy"]'::jsonb,0,'Motors turn electricity into motion.','original'),
('127.391.d.7.A',4,'A gear train in a machine is used to change speed and:','["color", "torque", "voltage rating", "weight of fuel"]'::jsonb,1,'Gears trade speed for turning force.','original'),
('127.391.d.7.B',3,'An electrician installs and repairs:','["tree roots", "plumbing only", "wiring and electrical systems", "paint colors"]'::jsonb,2,'Electricians work with electrical systems.','original'),
('127.391.d.7.B',4,'A mechanical technician commonly works on:','["menu plans", "hair styles", "tax forms", "machines and moving parts"]'::jsonb,3,'Mechanical technicians service machinery.','original'),
('127.391.d.7.C',3,'Electric vehicles are an emerging trend because they replace combustion engines with:','["electric motors", "sails", "pedals", "steam boilers"]'::jsonb,0,'EVs use motors powered by batteries.','original'),
('127.391.d.7.C',4,'Regenerative braking in modern vehicles converts braking energy into:','["extra heat only", "stored electrical energy", "fuel vapor", "water"]'::jsonb,1,'The motor acts as a generator to recharge the battery.','original'),
('127.391.d.7.D',3,'Electric current is the flow of:','["heat", "light", "electric charge", "magnetism"]'::jsonb,2,'Current is moving charge, usually electrons.','original'),
('127.391.d.7.D',4,'A material that allows current to flow easily is called a:','["dielectric", "insulator", "shield", "conductor"]'::jsonb,3,'Conductors pass current easily.','original'),
('127.391.d.8.A',3,'A decision matrix helps a team choose a design by:','["scoring options against criteria", "picking the cheapest only", "voting by volume", "flipping a coin"]'::jsonb,0,'Matrices compare options objectively.','original'),
('127.391.d.8.A',4,'In a decision matrix, criteria that matter more to the team are given higher:','["volume", "weights", "noise", "margins"]'::jsonb,1,'Weighting reflects each criterion''s importance.','original'),
('127.391.d.8.B',3,'On a design team, the person who records meeting decisions is the:','["customer", "competitor", "recorder", "supplier"]'::jsonb,2,'The recorder keeps team notes.','original'),
('127.391.d.8.B',4,'Rotating roles on a project team helps members:','["avoid responsibility", "skip the work", "lose track of tasks", "gain a variety of skills"]'::jsonb,3,'Different roles build different skills.','original'),
('127.391.d.8.C',3,'When two teammates disagree, a good first step is to:','["listen and compare the evidence", "walk away", "make a threat", "shout"]'::jsonb,0,'Evidence-based discussion resolves disagreements.','original'),
('127.391.d.8.C',4,'Consensus decision making means the team:','["takes a majority only", "reaches an agreement everyone can support", "avoids deciding", "lets the loudest decide"]'::jsonb,1,'Consensus seeks agreement all can accept.','original'),
('127.391.d.8.D',3,'In a project notebook, sketches of design ideas should be:','["removed later", "left blank", "dated and labeled", "kept secret"]'::jsonb,2,'Dated, labeled sketches document the design.','original'),
('127.391.d.8.D',4,'A properly kept project notebook can help prove who first came up with an idea, which matters for a:','["lunch menu", "school dance", "parking permit", "patent claim"]'::jsonb,3,'Notebooks document invention dates.','original'),
('127.391.d.8.E',3,'A scale model is built to:','["test a design before full production", "avoid measurements", "replace all drawings", "increase cost"]'::jsonb,0,'Models reveal problems cheaply.','original'),
('127.391.d.8.E',4,'Testing a model in a wind tunnel is mainly done to see how it responds to:','["taxes", "airflow", "gossip", "music"]'::jsonb,1,'Wind tunnels test aerodynamic behavior.','original'),
('127.391.d.8.F',3,'A good project presentation begins by stating the:','["weather outside", "team''s snack order", "problem being solved", "final grade"]'::jsonb,2,'Audiences need the problem first.','original'),
('127.391.d.8.F',4,'To make results easy to follow in a presentation, data is best shown with:','["tiny unlabeled numbers", "a long paragraph", "blurry photos", "clear charts and labels"]'::jsonb,3,'Clear visuals communicate results.','original'),
('127.391.d.9.A',3,'Before drawing in CAD, you should set the drawing''s:','["units and limits", "font of your name", "volume level", "screen brightness"]'::jsonb,0,'Units and limits set up the drawing space.','original'),
('127.391.d.9.A',4,'In CAD, a tool that removes a portion of a line that extends past another line is:','["mirror", "trim", "copy", "fill"]'::jsonb,1,'Trim cleans up overlapping geometry.','original'),
('127.391.d.9.B',3,'Saving a CAD drawing frequently helps prevent:','["line weights", "screen glare", "losing your work", "extra layers"]'::jsonb,2,'Frequent saves protect against crashes.','original'),
('127.391.d.9.B',4,'A reusable group of geometry, such as a bolt, saved so it can be inserted into other drawings is called a:','["layer", "viewport", "grid", "block"]'::jsonb,3,'Blocks store geometry for reuse.','original'),
('127.391.d.9.C',3,'In engineering drawings, a dashed line is usually used to show:','["hidden features", "center of a circle", "dimensions", "visible edges"]'::jsonb,0,'Hidden lines show edges not visible in the view.','original'),
('127.391.d.9.C',4,'A thick, continuous line on a drawing represents:','["dimension lines", "visible edges", "hidden edges", "centerlines"]'::jsonb,1,'Object lines show visible outlines.','original'),
('127.391.d.9.D',3,'A single-view drawing is most suitable for objects that are:','["moving", "hollow with inner ribs", "flat with uniform thickness", "complex and curved in 3D"]'::jsonb,2,'Flat parts need only one view plus a thickness note.','original'),
('127.391.d.9.D',4,'A gasket cut from a flat sheet can usually be described by a single view with a note giving its:','["age", "smell", "owner", "thickness"]'::jsonb,3,'A note supplies the missing dimension.','original'),
('127.391.d.9.E',3,'The three views most commonly shown in a multi-view orthographic drawing are front, top, and:','["right side", "angle", "underneath", "inside"]'::jsonb,0,'Front, top, and right side views describe most objects.','original'),
('127.391.d.9.E',4,'In orthographic projection, views are drawn with projectors that are:','["bent", "perpendicular to the plane of projection", "converging at a point", "tilted at random"]'::jsonb,1,'Parallel, perpendicular projectors keep true shapes.','original'),
('127.391.d.9.F',3,'Dimensions on a working drawing should be placed so they are:','["hidden under the object", "written in red only", "easy to read and not crowded", "scattered randomly"]'::jsonb,2,'ANSI practice calls for clear dimension placement.','original'),
('127.391.d.9.F',4,'Under ANSI practice, a dimension line has arrowheads that touch the:','["border", "title block", "revision table", "extension lines"]'::jsonb,3,'Arrowheads end at the extension lines.','original'),
('127.391.d.9.G',3,'A pictorial drawing in which the three axes are 120 degrees apart is:','["isometric", "oblique", "perspective", "sectional"]'::jsonb,0,'Isometric axes are 120 degrees apart.','original'),
('127.391.d.9.H',3,'A section view is used to show:','["the weight", "interior details", "the supplier", "only the color"]'::jsonb,1,'Cutting through an object reveals inside features.','original'),
('127.391.d.9.H',4,'The diagonal lines in a section view are called:','["extension lines", "dimension lines", "section lines", "phantom lines"]'::jsonb,2,'Section lines mark cut surfaces.','original'),
('127.391.d.10.A',3,'A well-defined engineering problem statement should describe:','["the team''s names", "the final answer", "the budget only", "the need to be solved"]'::jsonb,3,'A problem statement defines the need, not the solution.','original'),
('127.391.d.10.A',4,'Which is the best problem statement for an engineer?','["Students need a way to carry lab tools safely between rooms.", "Carts are good.", "I like tools.", "Build a cart."]'::jsonb,0,'It states a need without prescribing the solution.','original'),
('127.391.d.10.B',3,'A requirement such as ''must hold 10 pounds'' is an example of a:','["opinion", "measurable specification", "slogan", "guess"]'::jsonb,1,'Measurable requirements can be tested.','original'),
('127.391.d.10.B',4,'Goals differ from objectives because objectives are generally:','["vague wishes", "unwritten", "specific and measurable", "unrelated"]'::jsonb,2,'Objectives turn goals into measurable targets.','original'),
('127.391.d.10.C',3,'Which of these is a design parameter?','["The room color", "The weather last week", "The designer''s age", "The material to be used"]'::jsonb,3,'Parameters define materials, sizes, and resources.','original'),
('127.391.d.10.C',4,'Available personnel, tools, and time are examples of design:','["resources", "errors", "symbols", "slogans"]'::jsonb,0,'Resources limit what can be built.','original'),
('127.391.d.10.D',3,'A constraint limits a design. Which is an example?','["An optional color", "A maximum budget of $500", "A friendly name", "An unlimited timeline"]'::jsonb,1,'A budget cap is a constraint.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_57_v1'
from (values
('127.391.d.10.D',4,'A design that must meet fire code is limited by a:','["naming rule", "fun feature", "safety constraint", "color preference"]'::jsonb,2,'Codes impose safety constraints.','original'),
('127.391.d.10.E',3,'Creating several possible solutions before choosing one helps a team avoid:','["drawing", "using materials", "all testing", "settling on a weak first idea"]'::jsonb,3,'Alternatives lead to better choices.','original'),
('127.391.d.10.E',4,'Techniques like sketching, brainstorming, and mind maps are used to:','["generate alternative solutions", "ship the product", "finalize the budget", "test fasteners"]'::jsonb,0,'These techniques produce options.','original'),
('127.391.d.10.F',3,'A fair test of a design changes only one variable at a time so the team can:','["hide the results", "identify its effect", "skip a trial", "avoid recording data"]'::jsonb,1,'Controlling variables isolates cause and effect.','original'),
('127.391.d.10.F',4,'Stress testing a bracket until it fails helps engineers find its:','["shipping date", "favorite size", "breaking point", "cost of paint"]'::jsonb,2,'Testing to failure shows maximum strength.','original'),
('127.391.d.10.G',3,'A decision tree helps engineers by:','["painting parts", "storing parts", "drawing floors", "mapping choices and outcomes"]'::jsonb,3,'Decision trees lay out options and consequences.','original'),
('127.391.d.10.G',4,'A design matrix ranks solutions by:','["scoring each against weighted criteria", "drawing straws", "asking one person''s taste", "alphabetical order"]'::jsonb,0,'Weighted scoring ranks designs objectively.','original'),
('127.391.d.10.H',3,'Failure mode analysis asks the question:','["What color is it?", "How could this design fail?", "Who designed it?", "Where was it made?"]'::jsonb,1,'It identifies ways a design could fail.','original'),
('127.391.d.10.H',4,'Reliability of a design is the probability that it will:','["be copied", "look attractive", "work as intended over time", "cost less"]'::jsonb,2,'Reliability measures dependable performance.','original'),
('127.391.d.10.I',3,'A project report should document the design, decisions made, and:','["the team''s lunch", "only the cover page", "unrelated opinions", "the results of testing"]'::jsonb,3,'Reports record what was learned.','original'),
('127.391.d.10.I',4,'The abstract of an engineering report is a short:','["summary of the project", "list of references", "table of costs", "drawing set"]'::jsonb,0,'Abstracts summarize the work.','original'),
('127.392.d.1.A',3,'An electronics technician typically needs training from a:','["cooking school", "community college or apprenticeship program", "art gallery", "stage show"]'::jsonb,1,'Technical training prepares electronics technicians.','original'),
('127.392.d.1.A',4,'Which job is part of the electronics career field?','["Landscape painter", "Pastry chef", "Avionics technician", "Court reporter"]'::jsonb,2,'Avionics technicians service aircraft electronics.','original'),
('127.392.d.1.B',3,'An industry certification in electronics shows that a worker has:','["avoided exams", "retired", "paid taxes", "met a recognized skill standard"]'::jsonb,3,'Certifications verify skills.','original'),
('127.392.d.1.B',4,'Which organization offers well-known certifications for electronics technicians, such as CET?','["ETA International", "The PTA", "The NFL", "The Red Cross"]'::jsonb,0,'ETA International awards the CET credential.','original'),
('127.392.d.1.C',3,'Copying a competitor''s circuit design without permission is an example of:','["fair testing", "intellectual property theft", "good teamwork", "original research"]'::jsonb,1,'Unauthorized copying violates IP rights.','original'),
('127.392.d.1.C',4,'Ethically, a technician who finds a safety defect in a product should:','["hide it", "joke about it", "report it", "sell it"]'::jsonb,2,'Safety defects must be reported.','original'),
('127.392.d.1.D',3,'Respecting diversity on a work team means:','["ignoring coworkers", "excluding differences", "copying one person", "valuing different backgrounds and ideas"]'::jsonb,3,'Respect means valuing each person''s perspective.','original'),
('127.392.d.1.D',4,'A diverse electronics team can benefit a company because members:','["bring different viewpoints to solve problems", "all think alike", "repeat each other", "avoid debate"]'::jsonb,0,'Varied viewpoints strengthen problem solving.','original'),
('127.392.d.1.E',3,'Discriminating against a coworker because of race or sex can result in:','["a promotion", "disciplinary action or legal penalties", "a raise", "a free lunch"]'::jsonb,1,'Discrimination has serious consequences.','original'),
('127.392.d.1.E',4,'Which federal law prohibits employment discrimination based on race, color, religion, sex, or national origin?','["The Homestead Act", "The Clean Air Act", "Title VII of the Civil Rights Act", "The Telegraph Act"]'::jsonb,2,'Title VII bars job discrimination on these bases.','original'),
('127.392.d.1.F',3,'Job shadowing lets a student:','["do the worker''s taxes", "own the shop", "get the worker''s license", "observe a worker on the job"]'::jsonb,3,'Shadowing is a short observation experience.','original'),
('127.392.d.1.F',4,'An internship is different from job shadowing because an intern usually:','["performs real tasks for the employer", "is not supervised", "only watches", "never works"]'::jsonb,0,'Interns do supervised work.','original'),
('127.392.d.1.G',3,'ABET accreditation tells students that an engineering or technology program meets:','["no standards", "quality standards", "a dress code", "a color code"]'::jsonb,1,'Accreditation verifies program quality.','original'),
('127.392.d.1.G',4,'Employers value graduates from ABET-accredited programs because their education has been:','["self-graded only", "never evaluated", "independently reviewed", "kept secret"]'::jsonb,2,'Outside reviewers check the program.','original'),
('127.392.d.2.A',3,'Why is teamwork important in electronics manufacturing?','["It lowers quality", "It prevents communication", "One person always does all work", "Complex products need many people''s skills"]'::jsonb,3,'Products require design, assembly, and test skills.','original'),
('127.392.d.2.A',4,'On a circuit board project, the person who solders and the person who tests must:','["communicate about problems", "work in secret", "avoid each other", "never share results"]'::jsonb,0,'Shared information prevents rework.','original'),
('127.392.d.2.B',3,'Effective problem solving on a team begins with:','["waiting", "defining the problem together", "guessing", "blaming someone"]'::jsonb,1,'A shared understanding starts the process.','original'),
('127.392.d.2.B',4,'Active listening during a team meeting includes:','["talking over others", "checking a phone", "paraphrasing what others said", "interrupting often"]'::jsonb,2,'Paraphrasing confirms understanding.','original'),
('127.392.d.2.C',3,'A good team leader shows a positive attitude by:','["criticizing in public", "taking all credit", "avoiding work", "encouraging others"]'::jsonb,3,'Leaders motivate the team.','original'),
('127.392.d.2.C',4,'A good team member who disagrees with a decision should:','["voice concerns respectfully", "sabotage the work", "stay silent and quit", "complain to outsiders"]'::jsonb,0,'Respectful input helps teams improve.','original'),
('127.392.d.3.A',3,'Which is the first phase of a project?','["Executing", "Initiating", "Closing", "Monitoring"]'::jsonb,1,'Projects begin by initiating.','original'),
('127.392.d.3.A',4,'The phase where a project''s results are delivered and records are finalized is:','["brainstorming", "initiating", "closing", "planning"]'::jsonb,2,'Closing wraps up the project.','original'),
('127.392.d.3.B',3,'A project schedule helps the team by showing:','["unrelated hobbies", "team ages", "only costs", "tasks and their deadlines"]'::jsonb,3,'Schedules list tasks and due dates.','original'),
('127.392.d.3.B',4,'A chart that shows tasks as horizontal bars over time is a:','["Gantt chart", "bar code", "schematic", "pie chart"]'::jsonb,0,'Gantt charts plot tasks against time.','original'),
('127.392.d.3.C',3,'In a simulated electronics enterprise, students may take roles such as:','["astronaut", "production manager", "movie star", "pilot"]'::jsonb,1,'Simulated companies mirror real job roles.','original'),
('127.392.d.3.C',4,'Running a school business that builds and sells kits helps students learn:','["only reading", "nothing about business", "how companies operate", "only drawing"]'::jsonb,2,'Real or simulated enterprises teach business operations.','original'),
('127.392.d.3.D',3,'A production plan for a single circuit project should list:','["just the team", "only the name", "only the color", "materials, steps, and time needed"]'::jsonb,3,'A plan covers what, how, and when.','original'),
('127.392.d.3.D',4,'A bill of materials in a production plan lists:','["every part needed", "customer names", "safety quiz scores", "employee pay"]'::jsonb,0,'A BOM itemizes all components.','original'),
('127.392.d.4.A',3,'A student must score 100% on an electrical safety test before:','["using a pencil", "using soldering equipment", "entering the cafeteria", "reading the book"]'::jsonb,1,'Safety tests gate access to hazardous tools.','original'),
('127.392.d.4.A',4,'Electronics safety tests are repeated each term so students stay:','["unprepared", "untested", "alert to hazards", "distracted"]'::jsonb,2,'Repetition reinforces safe habits.','original'),
('127.392.d.4.B',3,'Before operating an unfamiliar oscilloscope, you should read:','["a novel", "the cafeteria menu", "a news website", "the operator''s manual"]'::jsonb,3,'Manuals give safe operating procedures.','original'),
('127.392.d.4.B',4,'Where would you look to find a machine''s required lockout procedure?','["The equipment instruction manual", "A cookbook", "A phone book", "The school yearbook"]'::jsonb,0,'Manuals describe lockout steps.','original'),
('127.392.d.4.C',3,'Which U.S. agency sets and enforces workplace safety rules?','["FBI", "OSHA", "NASA", "NFL"]'::jsonb,1,'OSHA regulates workplace safety.','original'),
('127.392.d.4.C',4,'Employers are required by OSHA to provide workers with:','["free tools to keep", "guaranteed bonuses", "a workplace free from recognized hazards", "unlimited breaks"]'::jsonb,2,'The General Duty Clause requires hazard-free workplaces.','original'),
('127.392.d.4.D',3,'Lead-based solder is a hazard because lead is a:','["water filter", "safe mineral", "food additive", "toxic metal"]'::jsonb,3,'Lead harms the body.','original'),
('127.392.d.4.D',4,'The OSHA Hazard Communication Standard requires chemical containers to have:','["hazard labels", "bright colors only", "advertisements", "price tags only"]'::jsonb,0,'Labels communicate chemical hazards.','original'),
('127.392.d.4.E',3,'Old circuit boards and batteries should be disposed of through:','["a storm drain", "an e-waste recycling program", "a creek", "a backyard fire"]'::jsonb,1,'E-waste contains toxic metals.','original'),
('127.392.d.4.E',4,'Used flux and solder scraps should be placed in:','["a lunch bag", "a pocket", "a designated waste container", "a classmate''s desk"]'::jsonb,2,'Scraps go in labeled waste containers.','original'),
('127.392.d.4.F',3,'A soldering iron tip should be cleaned and:','["painted", "bent", "dropped", "tinned"]'::jsonb,3,'Tinning protects the tip and improves heat transfer.','original'),
('127.392.d.4.F',4,'Regular calibration of a meter ensures its readings stay:','["accurate", "louder", "random", "decorative"]'::jsonb,0,'Calibration keeps measurements correct.','original'),
('127.392.d.4.G',3,'Static-sensitive parts should be stored in:','["a coat pocket", "anti-static bags", "any open bin", "a wet cloth"]'::jsonb,1,'Anti-static bags protect ICs from ESD.','original'),
('127.392.d.4.G',4,'After use, a soldering iron should be returned to its:','["drawer while hot", "backpack", "stand", "pocket"]'::jsonb,2,'Hot irons belong in their holder.','original'),
('127.392.d.4.H',3,'A frayed power cord on a test instrument that is not repaired could cause:','["a quieter lab", "longer battery life", "cleaner signals", "an electric shock"]'::jsonb,3,'Damaged insulation exposes live conductors.','original'),
('127.392.d.4.H',4,'An uncalibrated meter used in repairs can lead to:','["wrong measurements and faulty repairs", "fewer tests", "perfect results", "lower bills"]'::jsonb,0,'Bad readings cause bad repairs.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
