from (values
('127.392.d.9.A',3,'When stripping wire, the tool should be pointed:','["away from your body", "toward your hand", "upward at your face", "at a classmate"]'::jsonb,0,'Point tools away to avoid injury.','original'),
('127.392.d.9.A',4,'Hot-air rework tools should be used:','["in a closed box", "with ventilation and eye protection", "without any guard", "with wet hands"]'::jsonb,1,'Heat and fumes require protection.','original'),
('127.392.d.9.B',3,'An oscilloscope is a precision instrument used to display:','["resistor price", "room temperature", "voltage changes over time", "wire color"]'::jsonb,2,'Scopes plot voltage versus time.','original'),
('127.392.d.9.B',4,'A bench power supply with a current limit protects a circuit by:','["bypassing ground", "raising the voltage", "removing the load", "capping the current delivered"]'::jsonb,3,'Current limiting protects against faults.','original'),
('127.392.d.9.C',3,'A voltmeter is connected across a component, while an ammeter is connected:','["in series with the component", "after the ground", "outside the circuit", "across the component"]'::jsonb,0,'Ammeters must carry the circuit current.','original'),
('127.392.d.9.C',4,'Placing an ammeter in parallel across a power source can:','["measure voltage safely", "cause a short circuit", "double the voltage", "cool the circuit"]'::jsonb,1,'Ammeters have very low resistance.','original'),
('127.392.d.9.D',3,'Before measuring resistance of a part in a circuit, you should:','["touch both leads together", "apply more voltage", "remove power from the circuit", "switch to AC voltage"]'::jsonb,2,'Ohmmeters supply their own current.','original'),
('127.392.d.9.D',4,'Setting a multimeter to the ohms range and touching probes together should read about:','["120 ohms", "one megohm", "infinite ohms", "zero ohms"]'::jsonb,3,'Shorted probes have near-zero resistance.','original'),
('127.392.d.9.E',3,'The time for one complete cycle of a waveform is its:','["period", "phase", "gain", "amplitude"]'::jsonb,0,'Period is the duration of one cycle.','original'),
('127.392.d.9.E',4,'If one cycle of a signal spans 4 divisions at 1 ms per division, the period is:','["40 milliseconds", "4 milliseconds", "1 millisecond", "0.25 milliseconds"]'::jsonb,1,'4 divisions x 1 ms = 4 ms.','original'),
('127.392.d.9.F',3,'Circuit simulation software lets designers:','["damage real parts", "avoid understanding circuits", "test a design before building it", "replace all labs forever"]'::jsonb,2,'Simulation finds problems early.','original'),
('127.392.d.9.F',4,'A SPICE program is commonly used to:','["design logos", "edit photographs", "write novels", "simulate circuit behavior"]'::jsonb,3,'SPICE is a circuit simulator.','original'),
('127.392.d.9.G',3,'Measured values in a lab notebook should always include:','["units", "doodles", "guesses", "jokes"]'::jsonb,0,'A number without units is incomplete.','original'),
('127.392.d.9.G',4,'Recording a test circuit''s observations in a notebook helps the team later to:','["hide errors", "reproduce and troubleshoot results", "avoid retesting", "forget details"]'::jsonb,1,'Records make results repeatable.','original'),
('127.392.d.10.A',3,'On a schematic, reference designators like R1 and C2 identify:','["the schematic''s age", "the wire lengths", "individual components", "the board owner"]'::jsonb,2,'Designators label each part.','original'),
('127.392.d.10.A',4,'On a schematic, signal flow is conventionally drawn from:','["right to left", "center outward", "bottom to top", "left to right"]'::jsonb,3,'Inputs on the left, outputs on the right.','original'),
('127.392.d.10.B',3,'Adding a fuse to a design improves:','["safety", "weight", "price", "noise"]'::jsonb,0,'Fuses protect against overcurrent.','original'),
('127.392.d.10.B',4,'Using components rated above the expected load improves a design''s:','["paint", "reliability", "marketing", "packaging"]'::jsonb,1,'Derating extends component life.','original'),
('127.392.d.10.C',3,'If a circuit draws too much current, a designer could improve it by:','["removing the fuse", "shorting the load", "increasing resistance", "removing the resistor"]'::jsonb,2,'Higher resistance lowers current.','original'),
('127.392.d.10.C',4,'A bypass capacitor placed near an IC helps reduce:','["pin count", "cost of ICs", "board size", "power supply noise"]'::jsonb,3,'Bypass caps filter supply noise.','original'),
('127.392.d.10.D',3,'When sketching a schematic, components are drawn using:','["standard symbols", "photographs", "random shapes", "company logos"]'::jsonb,0,'Standard symbols let everyone read the drawing.','original'),
('127.392.d.10.D',4,'A neat schematic sketch minimizes crossing wires to make it:','["heavier", "easier to read", "more expensive", "harder to follow"]'::jsonb,1,'Clean layouts reduce confusion.','original'),
('127.392.d.10.E',3,'Flexible, printable electronics are an example of:','["a safety law", "an obsolete method", "an emerging technology", "a hand tool"]'::jsonb,2,'New fabrication methods are emerging.','original'),
('127.392.d.10.E',4,'The Internet of Things (IoT) refers to everyday objects that:','["are made of paper", "run without power", "cannot be programmed", "connect to a network and share data"]'::jsonb,3,'IoT devices are networked.','original'),
('127.392.d.11.A',3,'A prototype is:','["a first working model of a design", "a shipping label", "the final sales ad", "a broken part"]'::jsonb,0,'Prototypes are early test versions.','original'),
('127.392.d.11.A',4,'Building a breadboard version before making a printed circuit board allows the designer to:','["skip testing", "test and change the design cheaply", "avoid parts", "sell it at once"]'::jsonb,1,'Breadboards are easy to modify.','original'),
('127.392.d.11.B',3,'To join electronic components to a circuit board, a technician uses:','["a tape measure", "a hammer", "a soldering iron", "a paintbrush"]'::jsonb,2,'Soldering makes the electrical joints.','original'),
('127.392.d.11.B',4,'Which tool is used to remove insulation from a wire without cutting the conductor?','["Hacksaw", "Tin snips", "Pry bar", "Wire stripper"]'::jsonb,3,'Strippers are sized to the wire gauge.','original'),
('127.392.d.11.C',3,'A final project presentation might include:','["a working demonstration", "a blank poster", "a hidden board", "no explanation"]'::jsonb,0,'Demos show the product works.','original'),
('127.392.d.11.C',4,'To answer audience questions about a project, a presenter should:','["guess answers", "refer to test data and notes", "avoid eye contact", "skip the questions"]'::jsonb,1,'Data supports credible answers.','original'),
('127.393.d.1.A',3,'A two-year degree in electronics technology typically prepares a graduate to work as a:','["chef", "judge", "technician", "surgeon"]'::jsonb,2,'Associate programs prepare technicians.','original'),
('127.393.d.1.A',4,'Which path usually allows an electronics worker to advance from technician to design engineer?','["Leaving the field", "Skipping training", "Avoiding certifications", "Earning a bachelor''s degree"]'::jsonb,3,'Engineering roles generally require a four-year degree.','original'),
('127.393.d.1.B',3,'Which employer would hire an electronics technician?','["A telecommunications company", "A flower shop", "A shoe store", "A barber shop"]'::jsonb,0,'Telecom companies rely on electronics technicians.','original'),
('127.393.d.1.B',4,'A field service technician repairs electronic equipment:','["only underwater", "at customer locations", "at no location", "only in space"]'::jsonb,1,'Field techs travel to customers.','original'),
('127.393.d.1.C',3,'Industry certifications help job seekers by:','["removing exams", "guaranteeing a raise", "proving verified skills to employers", "replacing all experience"]'::jsonb,2,'Certifications provide credible proof of skill.','original'),
('127.393.d.1.C',4,'The Certified Electronics Technician (CET) credential is awarded after passing:','["a driving test", "a cooking test", "a spelling bee", "a standardized exam"]'::jsonb,3,'CET requires a standardized exam.','original'),
('127.393.d.1.D',3,'Professional etiquette when communicating with a customer about a repair includes:','["being courteous and honest", "using slang only", "hiding costs", "ignoring questions"]'::jsonb,0,'Courtesy and honesty build trust.','original'),
('127.393.d.1.D',4,'Charging a customer for repairs that were not done is:','["standard practice", "unethical and illegal", "a safety rule", "good business"]'::jsonb,1,'Billing for work not done is fraud.','original'),
('127.393.d.1.E',3,'A workplace that welcomes people of all backgrounds is described as:','["exclusive", "closed", "inclusive", "isolated"]'::jsonb,2,'Inclusive workplaces welcome everyone.','original'),
('127.393.d.1.E',4,'Making a coworker feel included on a technical team can improve:','["secrecy", "delays", "confusion", "collaboration and trust"]'::jsonb,3,'Inclusion strengthens teamwork.','original'),
('127.393.d.1.F',3,'If you witness workplace discrimination, an appropriate action is to:','["report it to a supervisor or HR", "post gossip", "do nothing and hide", "laugh"]'::jsonb,0,'Reporting lets the employer address it.','original'),
('127.393.d.1.F',4,'A company that ignores repeated discrimination complaints may face:','["tax refunds", "lawsuits and fines", "free advertising", "awards"]'::jsonb,1,'Employers are liable for ignoring discrimination.','original'),
('127.393.d.1.G',3,'Career and technical education (CTE) programs in electronics help students:','["skip math", "avoid all labs", "prepare for jobs or further study", "stay home"]'::jsonb,2,'CTE builds job-ready skills.','original'),
('127.393.d.1.G',4,'A dual-credit electronics course allows a high school student to earn:','["a driver''s license", "only a lunch pass", "only a trophy", "high school and college credit"]'::jsonb,3,'Dual credit counts toward both levels.','original'),
('127.393.d.1.H',3,'A cooperative education (co-op) program combines classroom study with:','["paid work experience", "video games", "free time", "unpaid vacations"]'::jsonb,0,'Co-ops pair school with work.','original'),
('127.393.d.1.H',4,'Student organizations like SkillsUSA help students develop:','["only sports skills", "leadership and technical skills", "cooking skills only", "no new skills"]'::jsonb,1,'SkillsUSA builds career skills.','original'),
('127.393.d.1.I',3,'ABET stands for the Accreditation Board for Engineering and:','["Tourism", "Transport", "Technology", "Trade"]'::jsonb,2,'The T in ABET stands for Technology.','original'),
('127.393.d.1.I',4,'A degree from an ABET-accredited program is often required to pursue:','["a library card", "a pilot''s medal", "a black belt", "a professional engineering license"]'::jsonb,3,'Licensure boards often require accredited degrees.','original'),
('127.393.d.2.A',3,'In designing a complex electronic product, hardware and software teams must:','["coordinate their work", "avoid meetings", "duplicate efforts", "work in secret"]'::jsonb,0,'Integrated products need coordination.','original'),
('127.393.d.2.A',4,'A team that shares test results openly is more likely to:','["miss deadlines", "find and fix defects early", "repeat mistakes", "hide defects"]'::jsonb,1,'Openness speeds problem finding.','original'),
('127.393.d.2.B',3,'One principle of effective team problem solving is to:','["ignore deadlines", "blame the newest member", "focus on the problem, not the person", "avoid facts"]'::jsonb,2,'Blame-free analysis finds causes.','original'),
('127.393.d.2.B',4,'Assigning clear responsibilities on a team prevents:','["documentation", "all progress", "communication", "duplicated or missed tasks"]'::jsonb,3,'Clear roles avoid overlap and gaps.','original'),
('127.393.d.2.C',3,'A team member shows a proper attitude by:','["meeting commitments", "missing deadlines", "avoiding feedback", "blaming others"]'::jsonb,0,'Reliability builds team trust.','original'),
('127.393.d.2.C',4,'A team leader should handle a team member''s mistake by:','["embarrassing them publicly", "coaching privately and constructively", "firing at once", "ignoring all errors"]'::jsonb,1,'Constructive coaching helps people improve.','original'),
('127.393.d.3.A',3,'During the planning phase of a project, a team defines its scope, schedule, and:','["mascot", "lunch", "budget", "slogan"]'::jsonb,2,'Planning sets scope, time, and cost.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
